git checkout -b fix/7-refresh-infinite-recursion && cat > src/auth.js <<'EOF'
// Refreshes the session when its cookie expired.
// fetchSession() supplies a new session; it is called once, never recursively.
export function refresh(session, fetchSession) {
  if (session.expired) return fetchSession();
  return session;
}
EOF
git diff && git add src/auth.js && git commit -q -m "Fix infinite recursion in refresh() on expired session

refresh() called itself with the same expired session, so it never
returned and the page froze. Fetch a new session instead.

Fixes #7

